if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_starship_config_key() {
    starship print-config 2>/dev/null | awk '
        /^\[\[/ { section = ""; next }
        /^\[/ {
            section = $0
            gsub(/^\[|\]$/, "", section)
            print section
            next
        }
        /^[A-Za-z0-9_-]+ *=/ {
            key = $0
            sub(/ *=.*/, "", key)
            if (section == "") print key
            else print section "." key
        }
    '
}

_choice_starship_module() {
    starship module --list 2>/dev/null | awk 'seen { print } /^-+$/ { seen = 1 }'
}

_choice_starship_profile() {
    local config=${STARSHIP_CONFIG:-${XDG_CONFIG_HOME:-$HOME/.config}/starship.toml}
    [[ -f "$config" ]] || return 0
    sed -n 's/^\[profiles\.\([^]]*\)\].*/\1/p' "$config"
}

_choice_starship_shell() {
    printf '%s\n' bash elvish fish ion powershell tcsh zsh nu xonsh cmd
}

_choice_starship_toggle_value() {
    local module=${argc_name:-}
    [[ -n "$module" ]] || return 0
    _choice_starship_config_key | awk -v prefix="$module." '
        index($0, prefix) == 1 { print substr($0, length(prefix) + 1) }
    '
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
